package com.newerstylehitsplats;

import java.util.ArrayList;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import net.runelite.api.Actor;

final class HitsplatTracker
{
	private static final int MAX_HITSPLATS_PER_ACTOR = 4;
	private final Map<Actor, List<TrackedHitsplat>> hitsplats = new IdentityHashMap<>();

	synchronized void add(Actor actor, int amount, int type, int disappearsOnGameCycle,
		int currentGameCycle, List<CombatIcon> icons)
	{
		if (disappearsOnGameCycle <= currentGameCycle)
		{
			return;
		}

		List<TrackedHitsplat> actorHitsplats = hitsplats.computeIfAbsent(actor, ignored -> new ArrayList<>());
		removeExpired(actorHitsplats, currentGameCycle);

		boolean[] occupiedSlots = new boolean[MAX_HITSPLATS_PER_ACTOR];
		for (TrackedHitsplat hitsplat : actorHitsplats)
		{
			occupiedSlots[hitsplat.getSlot()] = true;
		}

		int slot = firstFreeSlot(occupiedSlots);
		if (slot == -1)
		{
			TrackedHitsplat earliest = actorHitsplats.get(0);
			for (TrackedHitsplat hitsplat : actorHitsplats)
			{
				if (hitsplat.getDisappearsOnGameCycle() < earliest.getDisappearsOnGameCycle())
				{
					earliest = hitsplat;
				}
			}
			slot = earliest.getSlot();
			actorHitsplats.remove(earliest);
		}

		actorHitsplats.add(new TrackedHitsplat(
			actor, amount, type, currentGameCycle, disappearsOnGameCycle, slot, icons));
	}

	synchronized List<TrackedHitsplat> snapshot(int currentGameCycle)
	{
		List<TrackedHitsplat> result = new ArrayList<>();
		Iterator<Map.Entry<Actor, List<TrackedHitsplat>>> iterator = hitsplats.entrySet().iterator();
		while (iterator.hasNext())
		{
			List<TrackedHitsplat> actorHitsplats = iterator.next().getValue();
			removeExpired(actorHitsplats, currentGameCycle);
			if (actorHitsplats.isEmpty())
			{
				iterator.remove();
			}
			else
			{
				result.addAll(actorHitsplats);
			}
		}
		return result;
	}

	synchronized void clear()
	{
		hitsplats.clear();
	}

	private static void removeExpired(List<TrackedHitsplat> hitsplats, int currentGameCycle)
	{
		hitsplats.removeIf(hitsplat -> hitsplat.getDisappearsOnGameCycle() <= currentGameCycle);
	}

	private static int firstFreeSlot(boolean[] occupiedSlots)
	{
		for (int slot = 0; slot < occupiedSlots.length; slot++)
		{
			if (!occupiedSlots[slot])
			{
				return slot;
			}
		}
		return -1;
	}
}

package com.newerstylehitsplats;

import java.util.List;
import net.runelite.api.Actor;

final class TrackedHitsplat
{
	private final Actor actor;
	private final int amount;
	private final int type;
	private final int appliedOnGameCycle;
	private final int disappearsOnGameCycle;
	private final int slot;
	private final List<CombatIcon> icons;

	TrackedHitsplat(Actor actor, int amount, int type, int appliedOnGameCycle,
		int disappearsOnGameCycle, int slot, List<CombatIcon> icons)
	{
		this.actor = actor;
		this.amount = amount;
		this.type = type;
		this.appliedOnGameCycle = appliedOnGameCycle;
		this.disappearsOnGameCycle = disappearsOnGameCycle;
		this.slot = slot;
		this.icons = List.copyOf(icons);
	}

	Actor getActor()
	{
		return actor;
	}

	int getAmount()
	{
		return amount;
	}

	int getType()
	{
		return type;
	}

	int getDisappearsOnGameCycle()
	{
		return disappearsOnGameCycle;
	}

	int getAppliedOnGameCycle()
	{
		return appliedOnGameCycle;
	}

	int getSlot()
	{
		return slot;
	}

	List<CombatIcon> getIcons()
	{
		return icons;
	}
}

package com.newerstylehitsplats;

import java.util.List;
import java.util.Locale;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.ParamID;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

final class CombatStyleIconResolver
{
	private CombatStyleIconResolver()
	{
	}

	static List<CombatIcon> resolve(Client client)
	{
		int weaponType = client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY);
		int styleIndex = client.getVarpValue(VarPlayerID.COM_MODE);
		if (styleIndex == 4)
		{
			styleIndex += client.getVarbitValue(VarbitID.AUTOCAST_DEFMODE);
		}

		EnumComposition weaponStyles = client.getEnum(EnumID.WEAPON_STYLES);
		int styleEnumId = weaponStyles.getIntValue(weaponType);
		if (styleEnumId == -1)
		{
			return fallbackForSpecialWeapon(weaponType, styleIndex);
		}

		int[] styleStructs = client.getEnum(styleEnumId).getIntVals();
		if (styleIndex < 0 || styleIndex >= styleStructs.length)
		{
			return List.of(CombatIcon.ATTACK);
		}

		StructComposition style = client.getStructComposition(styleStructs[styleIndex]);
		return iconsForStyleName(style.getStringValue(ParamID.ATTACK_STYLE_NAME), styleIndex);
	}

	static List<CombatIcon> iconsForStyleName(String styleName)
	{
		return iconsForStyleName(styleName, -1);
	}

	static List<CombatIcon> iconsForStyleName(String styleName, int styleIndex)
	{
		if (styleName == null)
		{
			return List.of(CombatIcon.ATTACK);
		}

		switch (styleName.toUpperCase(Locale.ROOT))
		{
			case "AGGRESSIVE":
				return List.of(CombatIcon.STRENGTH);
			case "DEFENSIVE":
				// RuneLite's weapon-style enum labels staff index 5 as Defensive,
				// even though it is the Magic + Defence autocast mode.
				if (styleIndex == 5)
				{
					return List.of(CombatIcon.MAGIC, CombatIcon.DEFENCE);
				}
				return List.of(CombatIcon.DEFENCE);
			case "RANGING":
			case "RAPID":
				return List.of(CombatIcon.RANGED);
			case "LONGRANGE":
			case "LONG RANGE":
				return List.of(CombatIcon.RANGED, CombatIcon.DEFENCE);
			case "CASTING":
			case "AUTOCAST":
				return List.of(CombatIcon.MAGIC);
			case "DEFENSIVE CASTING":
			case "DEFENSIVE AUTOCAST":
				return List.of(CombatIcon.MAGIC, CombatIcon.DEFENCE);
			case "CONTROLLED":
				return List.of(CombatIcon.ATTACK, CombatIcon.STRENGTH, CombatIcon.DEFENCE);
			case "ACCURATE":
			default:
				return List.of(CombatIcon.ATTACK);
		}
	}

	static List<CombatIcon> fallbackForSpecialWeapon(int weaponType, int styleIndex)
	{
		if ((weaponType == 22 && styleIndex == 1)
			|| (weaponType == 30 && (styleIndex == 1 || styleIndex == 2)))
		{
			return List.of(CombatIcon.STRENGTH);
		}
		if ((weaponType == 22 || weaponType == 30) && styleIndex == 3)
		{
			return List.of(CombatIcon.DEFENCE);
		}
		if (weaponType == 22 && styleIndex == 4)
		{
			return List.of(CombatIcon.MAGIC);
		}
		if (weaponType == 22 && styleIndex == 5)
		{
			return List.of(CombatIcon.MAGIC, CombatIcon.DEFENCE);
		}
		return List.of(CombatIcon.ATTACK);
	}
}

package com.newerstylehitsplats;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.AsyncBufferedImage;

@PluginDescriptor(
	name = "Newer Style HitSplats",
	description = "Displays compact 2010-era rectangular hitsplats with combat skill icons",
	tags = {"hitsplat", "newer", "2010", "combat", "cosmetic"}
)
public class NewerStyleHitsplatsPlugin extends Plugin
{
	private static final int MANUAL_SPELL_TIMEOUT_TICKS = 8;

	private static final String[] CONFIG_KEYS =
	{
		"showMyHits",
		"showIncomingHits",
		"showOtherHits",
		"scale",
		"fadeOut",
		"opacity",
		"multiplyByTen"
	};

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private NewerStyleHitsplatsOverlay overlay;

	@Inject
	private SpriteManager spriteManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private NewerStyleHitsplatsConfig config;

	@Inject
	private ConfigManager configManager;

	private final HitsplatTracker tracker = new HitsplatTracker();
	private final Map<Actor, Integer> manualSpellTargets = new IdentityHashMap<>();

	private final Map<CombatIcon, BufferedImage> icons = new ConcurrentHashMap<>();

	private volatile boolean running;

	@Provides
	NewerStyleHitsplatsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(NewerStyleHitsplatsConfig.class);
	}

	@Override
	protected void startUp()
	{
		migrateLegacyConfig();
		running = true;
		overlayManager.add(overlay);
		loadIcons();
	}

	private void migrateLegacyConfig()
	{
		for (String key : CONFIG_KEYS)
		{
			if (configManager.getConfiguration(NewerStyleHitsplatsConfig.GROUP, key) != null)
			{
				continue;
			}

			String legacyValue = configManager.getConfiguration(NewerStyleHitsplatsConfig.LEGACY_GROUP, key);
			if (legacyValue != null)
			{
				configManager.setConfiguration(NewerStyleHitsplatsConfig.GROUP, key, legacyValue);
			}
		}
	}

	@Override
	protected void shutDown()
	{
		running = false;
		overlayManager.remove(overlay);
		tracker.clear();
		manualSpellTargets.clear();
		icons.clear();
		overlay.clearImageCache();
	}

	HitsplatTracker getTracker()
	{
		return tracker;
	}

	Map<CombatIcon, BufferedImage> getIcons()
	{
		return icons;
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Actor actor = event.getActor();
		Hitsplat hitsplat = event.getHitsplat();
		if (actor == null || hitsplat == null || !shouldTrack(actor, hitsplat))
		{
			return;
		}

		List<CombatIcon> icons = iconsFor(actor, hitsplat);
		tracker.add(
			actor,
			hitsplat.getAmount(),
			hitsplat.getHitsplatType(),
			hitsplat.getDisappearsOnGameCycle(),
			client.getGameCycle(),
			icons);
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		Widget selectedWidget = client.getSelectedWidget();
		int selectedInterface = selectedWidget == null
			? -1
			: WidgetUtil.componentToInterface(selectedWidget.getId());
		if (!isManualSpellTargetAction(event.getMenuAction(), selectedInterface))
		{
			return;
		}

		Actor target = event.getMenuEntry().getActor();
		if (target != null)
		{
			removeExpiredManualSpellTargets();
			manualSpellTargets.put(target, client.getTickCount() + MANUAL_SPELL_TIMEOUT_TICKS);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			tracker.clear();
			manualSpellTargets.clear();
		}
		if (event.getGameState().ordinal() >= GameState.LOGIN_SCREEN.ordinal())
		{
			loadIcons();
		}
	}

	private boolean shouldTrack(Actor actor, Hitsplat hitsplat)
	{
		Player localPlayer = client.getLocalPlayer();
		if (hitsplat.isMine())
		{
			return config.showMyHits();
		}
		if (actor == localPlayer)
		{
			return config.showIncomingHits();
		}
		return config.showOtherHits();
	}

	private List<CombatIcon> iconsFor(Actor actor, Hitsplat hitsplat)
	{
		int type = hitsplat.getHitsplatType();
		List<CombatIcon> specialIcons = specialIconsFor(type);
		if (!specialIcons.isEmpty())
		{
			return specialIcons;
		}
		if (hitsplat.isMine())
		{
			if (consumeManualSpellTarget(actor))
			{
				return List.of(CombatIcon.MAGIC);
			}
			return CombatStyleIconResolver.resolve(client);
		}
		if (actor == client.getLocalPlayer())
		{
			return List.of(CombatIcon.DEFENCE);
		}
		return List.of(CombatIcon.ATTACK);
	}

	static boolean isManualSpellTargetAction(MenuAction action, int selectedInterface)
	{
		return selectedInterface == InterfaceID.MAGIC_SPELLBOOK
			&& (action == MenuAction.WIDGET_TARGET_ON_NPC
				|| action == MenuAction.WIDGET_TARGET_ON_PLAYER);
	}

	private boolean consumeManualSpellTarget(Actor actor)
	{
		removeExpiredManualSpellTargets();
		return manualSpellTargets.remove(actor) != null;
	}

	private void removeExpiredManualSpellTargets()
	{
		int currentTick = client.getTickCount();
		manualSpellTargets.entrySet().removeIf(entry -> entry.getValue() < currentTick);
	}

	static List<CombatIcon> specialIconsFor(int hitsplatType)
	{
		switch (hitsplatType)
		{
			case HitsplatID.POISON:
				return List.of(CombatIcon.ANTIPOISON);
			case HitsplatID.VENOM:
				return List.of(CombatIcon.ANTIVENOM);
			case HitsplatID.PRAYER_DRAIN:
			case HitsplatID.CORRUPTION:
				return List.of(CombatIcon.PRAYER);
			case HitsplatID.BURN:
				return List.of(CombatIcon.MAGIC);
			case HitsplatID.BLEED:
				return List.of(CombatIcon.ATTACK);
			case HitsplatID.HEAL:
			case HitsplatID.DISEASE:
			case HitsplatID.DISEASE_BLOCKED:
			case HitsplatID.CYAN_UP:
			case HitsplatID.CYAN_DOWN:
			case HitsplatID.SANITY_DRAIN:
			case HitsplatID.SANITY_RESTORE:
			case HitsplatID.DOOM:
				return List.of(CombatIcon.HITPOINTS);
			default:
				return List.of();
		}
	}

	private void loadIcons()
	{
		for (CombatIcon icon : CombatIcon.values())
		{
			if (icons.containsKey(icon))
			{
				continue;
			}
			if (icon.getSource() == CombatIcon.Source.ITEM)
			{
				AsyncBufferedImage image = itemManager.getImage(icon.getImageId());
				icons.put(icon, image);
				image.onLoaded(() ->
				{
					if (running)
					{
						overlay.clearImageCache();
					}
				});
				continue;
			}

			spriteManager.getSpriteAsync(icon.getImageId(), 0, image ->
			{
				if (running && image != null)
				{
					icons.put(icon, image);
					overlay.clearImageCache();
				}
			});
		}
	}
}

package com.newerstylehitsplats;

import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.SpriteID;

enum CombatIcon
{
	ATTACK(Source.SPRITE, SpriteID.TinyCombatStaticons.ATTACK),
	STRENGTH(Source.SPRITE, SpriteID.TinyCombatStaticons.STRENGTH),
	DEFENCE(Source.SPRITE, SpriteID.TinyCombatStaticons.DEFENCE),
	RANGED(Source.SPRITE, SpriteID.TinyCombatStaticons.RANGED),
	MAGIC(Source.SPRITE, SpriteID.TinyCombatStaticons.MAGIC),
	HITPOINTS(Source.SPRITE, SpriteID.TinyCombatStaticons.HITPOINTS),
	PRAYER(Source.SPRITE, SpriteID.TinyCombatStaticons.PRAYER),
	ANTIPOISON(Source.ITEM, ItemID._4DOSEANTIPOISON),
	ANTIVENOM(Source.ITEM, ItemID.ANTIVENOM_4);

	enum Source
	{
		SPRITE,
		ITEM
	}

	private final Source source;
	private final int imageId;

	CombatIcon(Source source, int imageId)
	{
		this.source = source;
		this.imageId = imageId;
	}

	Source getSource()
	{
		return source;
	}

	int getImageId()
	{
		return imageId;
	}
}

package com.newerstylehitsplats;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(NewerStyleHitsplatsConfig.GROUP)
public interface NewerStyleHitsplatsConfig extends Config
{
	String GROUP = "newerstylehitsplats";
	String LEGACY_GROUP = "rs3stylehitsplats";

	@ConfigItem(
		keyName = "showMyHits",
		name = "Show your hits",
		description = "Show hits caused by your character",
		position = 0
	)
	default boolean showMyHits()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showIncomingHits",
		name = "Show incoming hits",
		description = "Show hits applied to your character",
		position = 1
	)
	default boolean showIncomingHits()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showOtherHits",
		name = "Show other hits",
		description = "Show hits caused by other players and NPCs",
